pub fn squash(v: &mut Vec<String>) {
    // Dedup consecutive runs in place (keep first of each run),
    // comparing on the original (untrimmed) values.
    let mut w = 0usize;
    for r in 0..v.len() {
        if w == 0 || v[r] != v[w - 1] {
            if r != w {
                v.swap(w, r);
            }
            w += 1;
        }
    }
    v.truncate(w);

    // Only now trim ASCII whitespace from both ends of survivors.
    for s in v.iter_mut() {
        *s = s.trim_matches(char::is_ascii_whitespace).to_string();
    }
}
