use std::sync::Arc;
use std::thread;

/// Maps `f` over `items` using exactly `workers` OS threads and returns the
/// results in the original input order.
pub fn parallel_map<T, R, F>(items: Vec<T>, f: F, workers: usize) -> Vec<R>
where
    T: Send + 'static,
    R: Send + 'static,
    F: Fn(T) -> R + Send + Sync + 'static,
{
    let workers = workers.max(1);
    let n = items.len();
    let f = Arc::new(f);

    // Split `items` into `workers` contiguous chunks of (nearly) equal size.
    let base = n / workers;
    let rem = n % workers;

    let mut handles = Vec::with_capacity(workers);
    for i in 0..workers {
        let len = base + if i < rem { 1 } else { 0 };
        // Move the next chunk out of `items` by value.
        let chunk: Vec<T> = items.drain(..len).collect();
        let f = f.clone();
        handles.push(thread::spawn(move || {
            chunk.into_iter().map(|x| f(x)).collect::<Vec<R>>()
        }));
    }

    // Join in spawn (chunk) order so results stay in original input order.
    let mut out = Vec::with_capacity(n);
    for handle in handles {
        out.extend(handle.join().expect("parallel_map worker panicked"));
    }
    out
}
