use std::marker::PhantomData;

/// An iterator over non-overlapping consecutive pairs of `&mut T` in a slice,
/// created by [`pairs_mut`]. An odd trailing element (if any) is dropped.
pub struct PairsMut<'a, T> {
    /// Pointer to the first element of the next pair.
    ptr: *mut T,
    /// Number of complete pairs left to yield.
    remaining: usize,
    /// Records that the unique `&'a mut [T]` borrow lives in this iterator
    /// (the raw pointer derives from it) for the whole `'a` lifetime.
    _unique: PhantomData<&'a mut T>,
}

/// Splits `s` into an iterator of non-overlapping consecutive mutable pairs.
///
/// For a slice `[a, b, c, d, e]` this yields `(a, b)` then `(c, d)`; the
/// trailing odd element is dropped.
pub fn pairs_mut<T>(s: &mut [T]) -> PairsMut<'_, T> {
    PairsMut {
        ptr: s.as_mut_ptr(),
        remaining: s.len() / 2,
        _unique: PhantomData,
    }
}

impl<'a, T: Sized> Iterator for PairsMut<'a, T> {
    type Item = (&'a mut T, &'a mut T);

    fn next(&mut self) -> Option<Self::Item> {
        if self.remaining == 0 {
            return None;
        }
        self.remaining -= 1;

        let first = self.ptr;
        let second = unsafe { self.ptr.offset(1) };

        // Advance past this pair; `2 * (pairs handed out)` never exceeds the
        // slice length, so the pointer stays within the allocation.
        self.ptr = unsafe { self.ptr.offset(2) };

        // SAFETY:
        // - `first` / `second` were derived from `s.as_mut_ptr()`, a valid,
        //   aligned pointer to the first element of a live slice of length
        //   `n`, advanced by exactly `2k` and `2k + 1` elements for the
        //   `k`-th pair, where `k < n / 2`; hence both indices lie in `[0, n)`.
        // - Every `&mut T` handed out so far covers elements `[2k, 2k + 1]`
        //   for a distinct `k`, so no two handed-out references overlap:
        //   the exclusivity invariant of `&mut` is preserved and each
        //   element is handed out at most once.
        // - The mutable borrow of the whole slice is uniquely held by this
        //   iterator (via `PhantomData<&'a mut T>`), so nothing else can
        //   alias these elements for `'a`.
        Some(unsafe { (&mut *first, &mut *second) })
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}
